-- A draft spread over monthly instalments: how many (2 to 24; null when there is no plan) and the
-- annual interest rate (0 to 30, up to two decimals) the schedule is worked out at.
ALTER TABLE invoice ADD COLUMN instalments INT;
ALTER TABLE invoice ADD COLUMN instalment_rate DECIMAL(5, 2) DEFAULT 0 NOT NULL;
-- The interest of the instalments not yet due that was dropped when a plan was paid off early; 0 when
-- it was not.
ALTER TABLE invoice ADD COLUMN interest_saved DECIMAL(19, 2) DEFAULT 0 NOT NULL;
-- The down payment a plan starts with: a percentage of the grand total (0 to 50, up to two
-- decimals) due on the issue date as instalment 0; 0 when there is none.
ALTER TABLE invoice ADD COLUMN plan_down_pct DECIMAL(5, 2) DEFAULT 0 NOT NULL;
-- The instalment of a plan the client skipped (it pays only its interest, and the instalments after
-- it are worked out again); null when none was.
ALTER TABLE invoice ADD COLUMN skipped_instalment INT;
-- The plan fee charged when the invoice was spread over instalments: the workspace's plan fee in US
-- dollars converted into the client's currency at the issue date's rate, rounded down; added to what
-- is spread over the instalments. 0 when there is none.
ALTER TABLE invoice ADD COLUMN plan_fee DECIMAL(19, 2) DEFAULT 0 NOT NULL;
