  dueDate: string | null;
  payment: string;
  interest: string;
  principal: string;
  balance: string;
  paid: string;
  lateInterest: string;
  status: InstalmentStatus;
}

// A payment to record against a sent invoice: the amount as entered, the date (yyyy-mm-dd) and the
  setSurcharge(invoiceId: number, surchargePct: string): Observable<InvoiceDetail> {
    return this.http.put<InvoiceDetail>(`/api/invoices/${invoiceId}/surcharge`, { surchargePct });
  }

  // Spreads a draft over monthly instalments (2 to 24) at an annual interest rate (0 to 30, up to two
  // decimals), after a down payment of a percentage of the grand total (0 to 50, up to two decimals);
  // refused (400) outside that, or (409) when it is not a draft.
  setPlan(invoiceId: number, instalments: string, instalmentRate: string, planDownPct: string): Observable<InvoiceDetail> {
    return this.http.put<InvoiceDetail>(`/api/invoices/${invoiceId}/plan`, { instalments, instalmentRate, planDownPct });
  }

    return this.http.post<InvoiceDetail>(`/api/invoices/${invoiceId}/waive-interest`, null);
  }

  // Skips an instalment of a sent plan: it pays only its interest and the instalments after it are
  // worked out again. Refused (409) for an overdue, paid or last instalment.
  skipInstalment(invoiceId: number, instalment: number): Observable<InvoiceDetail> {
    return this.http.post<InvoiceDetail>(`/api/invoices/${invoiceId}/instalments/${instalment}/skip`, null);
  }

  // Sends a draft invoice, issuing it today and due on the client's terms, or keeping a due date set
import { InstalmentStatus, InvoiceStatus, MilestoneStatus } from './invoice.service';

const STATUS_LABEL: Record<InvoiceStatus, string> = {
  DRAFT: 'Draft',
  SENT: 'Sent',
  PART_PAID: 'Part paid',
  PAID: 'Paid',
  PAID_LATE: 'Paid late',
  OVERDUE: 'Overdue',
  VOID: 'Void',
  CREDIT_NOTE: 'Credit note',
  CREDITED: 'Credited',
  WRITTEN_OFF: 'Written off',
  DISPUTED: 'Disputed',
  AWAITING_MILESTONE: 'Awaiting milestone',
};
const MILESTONE_STATUS_LABEL: Record<MilestoneStatus, string> = {
  PENDING: 'Pending',
  PAID: 'Paid',
  PART_PAID: 'Part paid',
  OVERDUE: 'Overdue',
  DUE: 'Due',
  DISPUTED: 'Disputed',
};
const INSTALMENT_STATUS_LABEL: Record<InstalmentStatus, string> = {
  PAID: 'Paid',
  PART_PAID: 'Part paid',
  OVERDUE: 'Overdue',
  DUE: 'Due',
};
// The currencies a client can be billed in.
export type Currency = 'USD' | 'EUR' | 'GBP' | 'JPY' | 'CHF';
export const CURRENCIES: readonly Currency[] = ['USD', 'EUR', 'GBP', 'JPY', 'CHF'];
// The symbol each currency's amounts are shown with, and how many decimals they have (yen none).
const SYMBOL: Record<Currency, string> = { USD: '$', EUR: '€', GBP: '£', JPY: '¥', CHF: 'CHF ' };
const NUMBER: Record<number, Intl.NumberFormat> = {
  0: new Intl.NumberFormat('en-US', { minimumFractionDigits: 0, maximumFractionDigits: 0 }),
  2: new Intl.NumberFormat('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }),
};

// How many decimals amounts in the currency have: 2, to the cent, or 0 for whole yen.
export function decimalsOf(currency: Currency): number {
  return currency === 'JPY' ? 0 : 2;
}

export function statusLabel(status: InvoiceStatus): string {
  return STATUS_LABEL[status];
}

export function milestoneStatusLabel(status: MilestoneStatus): string {
  return MILESTONE_STATUS_LABEL[status];
}

export function instalmentStatusLabel(status: InstalmentStatus): string {
  return INSTALMENT_STATUS_LABEL[status];
}

// Money from the server is already to the cent (whole yen for yen), so the number shown is exact:
